# Code generated by Claude
"""
Tests of src/stance_finder.py (B2.10) on made-up cases only: ball-shaped arm maps, empty or simple furniture maps, a made-up robot. No real map is built.

    python experiments/stance_finder_test.py

1. One point, a ball map: the valid spots form the disc the flipped map predicts (centre P - R(heading) (shoulder + ball centre), radius of the ball's slice), for several headings; the best
   stance is at the disc's centre with a score equal to the radius (the distance to the region's edge).
2. Two points: the valid region is the lens where the two discs overlap (area against the analytic lens), and the score is the distance to the lens's edge.
3. Pedestal height: a slab-shaped map is reachable only in a band of heights; the valid pedestal range found equals the analytic range and the chosen height is its middle.
4. Furniture: spots blocked by furniture (grown by the footprint) are not valid; the valid region is the disc minus the blocked cells; cells next to the blocked ones remain valid.
5. Both arms: where both arms reach, the stance ranks above a stance where only one arm does, even when the single-arm score is higher; the arm rule rounds to 1 cm and sends ties to the left.
6. Heading robustness: intersecting with the headings +-1 degree shrinks the region by the expected amount (the disc centre moves by |shoulder + ball centre| x 1 degree).
7. Holes: a hole in the map is an edge: no spot inside the hole is valid, and the best score in the annulus is half its width.
8. Bins: a point with a required bin uses only that bin's map; a point without one uses the union of the arm's bins.
9. Labels: a point labelled "left" excludes the right arm; a point no arm can reach gives no stance.
"""

import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import numpy as np  # noqa: E402

from src.furniture_map import FurnitureMap  # noqa: E402
from src.reach_map import ReachMap  # noqa: E402
from src.stance_finder import arm_for, find_stances, region_scores  # noqa: E402
from src.task_config import STANCE_CFG  # noqa: E402

results = []
RES = 0.01
CUBE = 0.01


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


ROBOT = {"shoulder": {"left": np.array([0.0, 0.03, 0.70]), "right": np.array([0.0, -0.03, 0.70])}, "torso_z0": 0.75, "lift_factor": 2.0, "base_z": 0.15,
         "footprint": np.array([[-0.02, -0.02], [0.02, -0.02], [0.02, 0.02], [-0.02, 0.02]])}
CFG = {**STANCE_CFG, "heading_robust_deg": 0.0, "window": 1.0, "max_stances": 50}


def shoulder_z(q):
    return ROBOT["base_z"] + ROBOT["torso_z0"] + ROBOT["lift_factor"] * q + ROBOT["shoulder"]["left"][2]


def ball_map(centre, radius, half_height=None, hole=None, side="left", bin=0):
    """A reach map of a ball (or a slab-limited ball) in the shoulder frame: centre (3,), radius, optional half height of a slab, optional (hole centre, hole radius)."""
    lo = np.floor((np.asarray(centre) - radius - 0.02) / CUBE) * CUBE
    n = int(np.ceil((2 * radius + 0.04) / CUBE))
    g = np.indices((n, n, n)).transpose(1, 2, 3, 0) * CUBE + lo + CUBE / 2
    ok = np.linalg.norm(g - centre, axis=-1) <= radius
    if half_height is not None:
        ok &= np.abs(g[..., 2] - centre[2]) <= half_height
    if hole is not None:
        ok &= np.linalg.norm(g - hole[0], axis=-1) > hole[1]
    return ReachMap(ok, lo, CUBE, side, bin)


def empty_furniture(size=4.0, blocked=None):
    n = int(2 * size / RES)
    base = np.zeros((n, n), bool)
    arm = np.zeros((n, n), bool)
    if blocked:
        base[blocked] = True
    return FurnitureMap({"base": base, "arm": arm}, (-size, -size), RES, 0.25)


def rot(theta):
    return np.array([[math.cos(theta), -math.sin(theta)], [math.sin(theta), math.cos(theta)]])


def point(x, y, z, arm="either", bin=0):
    return {"p": (x, y, z), "arm": arm, "bin": bin}


def main():
    F = empty_furniture()
    q = -0.1
    zP = shoulder_z(q)                                                     # a point level with the left shoulder at q = -0.1
    c, rho = np.array([0.40, 0.0, 0.0]), 0.25
    maps = {("left", 0): ball_map(c, rho)}
    print("\n1. one point, a ball map")
    for deg in (0, 90, 37):
        th = math.radians(deg)
        P = np.array([0.3, -0.2])
        p0 = P - rot(th) @ (ROBOT["shoulder"]["left"][:2] + c[:2])
        X, Y, S = region_scores([point(P[0], P[1], zP, "left")], maps, F, ROBOT, th, [q], CFG, centre=p0)
        s = S["left"][0]
        area = (s > 0).sum() * RES ** 2
        iy, ix = np.unravel_index(s.argmax(), s.shape)
        check(f"heading {deg}: the valid area is the disc's area pi r^2 (within 2 %)", abs(area - math.pi * rho ** 2) / (math.pi * rho ** 2) < 0.02, f"{area:.4f} vs {math.pi * rho ** 2:.4f} m^2")
        check(f"heading {deg}: the best spot is at the predicted centre (within 1.5 cm) with score = radius (within 1.5 cm)", math.hypot(X[iy, ix] - p0[0], Y[iy, ix] - p0[1]) < 0.015 and abs(s.max() - rho) < 0.015,
              f"centre error {1000 * math.hypot(X[iy, ix] - p0[0], Y[iy, ix] - p0[1]):.0f} mm, score {s.max():.3f}")
    st = find_stances([point(0.3, -0.2, zP, "left")], maps, F, ROBOT, CFG, headings=[math.radians(90)], pedestal_qs=[q])
    p0 = np.array([0.3, -0.2]) - rot(math.radians(90)) @ (ROBOT["shoulder"]["left"][:2] + c[:2])
    check("find_stances returns that stance first", st and math.hypot(st[0]["x"] - p0[0], st[0]["y"] - p0[1]) < 0.02 and st[0]["arm"] == "left" and abs(st[0]["q"] - q) < 1e-9, f"{st[0]['x']:.3f}, {st[0]['y']:.3f}, score {st[0]['score']:.3f}")

    print("\n2. two points: the lens")
    d = 0.20
    pts = [point(0.3, -0.2, zP, "left"), point(0.3, -0.2 + d, zP, "left")]
    X, Y, S = region_scores(pts, maps, F, ROBOT, 0.0, [q], CFG, centre=[0.3 - 0.4, -0.2])
    s = S["left"][0]
    lens = 2 * rho ** 2 * math.acos(d / (2 * rho)) - (d / 2) * math.sqrt(4 * rho ** 2 - d ** 2)
    area = (s > 0).sum() * RES ** 2
    check("the valid region is the lens of two discs 0.20 m apart (area within 3 %)", abs(area - lens) / lens < 0.03, f"{area:.4f} vs {lens:.4f} m^2")
    check("its best score is the lens's inscribed radius: rho - d/2 (within 1.5 cm)", abs(s.max() - (rho - d / 2)) < 0.015, f"{s.max():.3f} vs {rho - d / 2:.3f}")

    print("\n3. pedestal height")
    slab = {("left", 0): ball_map(c, rho, half_height=0.05)}
    qs = list(np.arange(-0.2, 0.0001, 0.005))
    P3 = (0.3, -0.2, 1.4)
    st = find_stances([point(*P3, "left")], slab, F, ROBOT, CFG, headings=[0.0], pedestal_qs=qs)
    q_lo_true, q_hi_true = (P3[2] - 0.05 - (ROBOT["base_z"] + ROBOT["torso_z0"] + ROBOT["shoulder"]["left"][2])) / 2, (P3[2] + 0.05 - (ROBOT["base_z"] + ROBOT["torso_z0"] + ROBOT["shoulder"]["left"][2])) / 2
    s0 = st[0]
    check("the valid pedestal range equals the analytic band (within 1 cm of stage travel)", abs(s0["q_lo"] - q_lo_true) < 0.01 and abs(s0["q_hi"] - q_hi_true) < 0.01, f"found {s0['q_lo']:.3f}..{s0['q_hi']:.3f}, analytic {q_lo_true:.3f}..{q_hi_true:.3f}")
    check("the chosen height is the middle of the range", abs(s0["q"] - 0.5 * (s0["q_lo"] + s0["q_hi"])) <= 0.0051, f"q = {s0['q']:.3f}")
    check("the torso height reported goes with that q", abs(s0["torso_z"] - (ROBOT["base_z"] + ROBOT["torso_z0"] + 2 * s0["q"])) < 1e-9)

    print("\n4. furniture")
    th = 0.0
    P = np.array([0.3, -0.2])
    p0 = P - rot(th) @ (ROBOT["shoulder"]["left"][:2] + c[:2])
    ix0 = int((p0[0] + 4) / RES)
    iy0 = int((p0[1] + 4) / RES)
    wall = (slice(iy0 - 40, iy0 + 40), slice(ix0 + 5, ix0 + 15))          # a wall 10 cm thick, 5 cm right of the disc's centre
    Fw = empty_furniture(blocked=wall)
    X, Y, S = region_scores([point(P[0], P[1], zP, "left")], maps, Fw, ROBOT, th, [q], CFG, centre=p0)
    s = S["left"][0]
    expect = (np.hypot(X - p0[0], Y - p0[1]) <= rho) & ~Fw.blocked(th, ROBOT["footprint"])[int((Y[0, 0] + 4) / RES - 0.5):int((Y[0, 0] + 4) / RES - 0.5) + X.shape[0], int((X[0, 0] + 4) / RES - 0.5):int((X[0, 0] + 4) / RES - 0.5) + X.shape[1]]
    mism = ((s > 0) != expect).sum() * RES ** 2
    check("the valid region is the disc minus the blocked cells (mismatch under 2 % of the disc)", mism < 0.02 * math.pi * rho ** 2, f"mismatch {mism:.4f} m^2 of {math.pi * rho ** 2:.3f}")
    wx = (X > p0[0] + 0.06) & (X < p0[0] + 0.14) & (np.abs(Y - p0[1]) < 0.3)
    check("no cell inside the wall (grown by the 4 cm footprint) is valid", not (s[wx] > 0).any())
    check("the cells left of the wall, further than the footprint from it, are valid", (s[(X < p0[0]) & (np.abs(Y - p0[1]) < 0.05) & (X > p0[0] - 0.15)] > 0).all())

    print("\n5. both arms")
    big = ball_map(c, 0.25, side="right")
    small = ball_map(c, 0.10, side="left")
    maps2 = {("left", 0): small, ("right", 0): big}
    P5 = [point(0.3, -0.2, zP, "either")]
    st = find_stances(P5, maps2, F, ROBOT, CFG, headings=[0.0], pedestal_qs=[q])
    check("the best stance is one where both arms reach, ranked above single-arm stances", st[0]["arm"] == "both" and st[0]["tier"] == 1, f"{st[0]['arm']}, score {st[0]['score']:.3f}")
    allst = find_stances(P5, maps2, F, ROBOT, {**CFG, "nms_distance": 0.0, "max_stances": 400}, headings=[0.0], pedestal_qs=[q])
    best_single = max((s_["score"] for s_ in allst if s_["tier"] == 0), default=0)
    check("a single-arm stance has a higher score than the both-arms stance (and still ranks below it)", best_single > st[0]["score"], f"{best_single:.3f} > {st[0]['score']:.3f}")
    check("the both-arms stance reports both scores", st[0]["score_left"] is not None and st[0]["score_right"] is not None and abs(st[0]["score"] - min(st[0]["score_left"], st[0]["score_right"])) < 1e-9)
    check("arm rule: scores 0.304 and 0.296 round to the same cm: the left arm", arm_for({"score_left": 0.304, "score_right": 0.296}) == "left")
    check("arm rule: 0.304 and 0.316 differ by more than 1 cm: the right arm", arm_for({"score_left": 0.304, "score_right": 0.316}) == "right")
    check("arm rule: exactly equal scores go to the left; an arm that does not reach loses", arm_for({"score_left": 0.2, "score_right": 0.2}) == "left" and arm_for({"score_left": None, "score_right": 0.1}) == "right" and arm_for({"score_left": 0.1, "score_right": None}) == "left")

    print("\n6. heading robustness")
    far = np.array([0.5, 0.0, 0.0])
    mp = {("left", 0): ball_map(far, rho)}
    P6 = [point(0.3, -0.2, zP, "left")]
    th = math.radians(20)
    p0 = np.array([0.3, -0.2]) - rot(th) @ (ROBOT["shoulder"]["left"][:2] + far[:2])
    X, Y, S0 = region_scores(P6, mp, F, ROBOT, th, [q], CFG, centre=p0)
    X, Y, S1 = region_scores(P6, mp, F, ROBOT, th, [q], {**CFG, "heading_robust_deg": 1.0}, centre=p0)
    shift = float(np.linalg.norm(ROBOT["shoulder"]["left"][:2] + far[:2])) * math.radians(1.0)
    check("the robust region is smaller", (S1["left"][0] > 0).sum() < (S0["left"][0] > 0).sum())
    check("its best score is lower by about the centre's shift (|shoulder + ball centre| x 1 degree)", abs((S0["left"][0].max() - S1["left"][0].max()) - shift) < 0.006, f"{1000 * (S0['left'][0].max() - S1['left'][0].max()):.1f} mm vs {1000 * shift:.1f} mm")

    print("\n7. a hole in the map")
    holed = {("left", 0): ball_map(c, 0.25, hole=(c, 0.05))}
    P = np.array([0.3, -0.2])
    p0 = P - ROBOT["shoulder"]["left"][:2] - c[:2]
    X, Y, S = region_scores([point(P[0], P[1], zP, "left")], holed, F, ROBOT, 0.0, [q], CFG, centre=p0)
    s = S["left"][0]
    inside = np.hypot(X - p0[0], Y - p0[1]) < 0.045
    check("no spot inside the hole is valid", not (s[inside] > 0).any())
    check("the best score is half the annulus's width (0.25 - 0.05) / 2 (within 1.5 cm)", abs(s.max() - 0.10) < 0.015, f"{s.max():.3f}")

    print("\n8. bins")
    m_a, m_b = ball_map(np.array([0.40, 0.0, 0.0]), 0.1, bin=0), ball_map(np.array([0.40, 0.6, 0.0]), 0.1, bin=1)
    mb = {("left", 0): m_a, ("left", 1): m_b}
    Pb = [0.3, -0.2, zP]
    Xa, Ya, Sa = region_scores([{"p": Pb, "arm": "left", "bin": 0}], mb, F, ROBOT, 0.0, [q], CFG, centre=[0.0, 0.0])
    Xb, Yb, Sb = region_scores([{"p": Pb, "arm": "left", "bin": 1}], mb, F, ROBOT, 0.0, [q], CFG, centre=[0.0, 0.0])
    Xu, Yu, Su = region_scores([{"p": Pb, "arm": "left", "bin": None}], mb, F, ROBOT, 0.0, [q], CFG, centre=[0.0, 0.0])
    aa, ab, au = (Sa["left"][0] > 0).sum(), (Sb["left"][0] > 0).sum(), (Su["left"][0] > 0).sum()
    check("a required bin uses only its map; no bin uses the union (two separate discs of 0.1 m)", abs(aa - ab) < 40 and abs(au - (aa + ab)) < 80 and abs(aa * RES ** 2 - math.pi * 0.01) < 0.002, f"areas {aa * RES ** 2:.4f}, {ab * RES ** 2:.4f}, union {au * RES ** 2:.4f} m^2")

    print("\n9. labels and unreachable points")
    st = find_stances([point(0.3, -0.2, zP, "left")], {("left", 0): ball_map(c, rho), ("right", 0): ball_map(c, rho, side="right")}, F, ROBOT, CFG, headings=[0.0], pedestal_qs=[q])
    check("a point labelled left leaves only the left arm", st and all(s_["arm"] == "left" and s_["score_right"] is None for s_ in st))
    st = find_stances([point(0.3, -0.2, zP + 2.0, "either")], maps2, F, ROBOT, CFG, headings=[0.0], pedestal_qs=[q])
    check("a point 2 m too high gives no stance", st == [])
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
